"spotnav-market-postcode-row",banner:"spotnav-banner",bannerBlocking:"spotnav-banner-blocking",bannerNotice:"spotnav-banner-notice",bannerCount:"spotnav-banner-count",status:"spotnav-status",chargeBar:"spotnav-charge-bar",chargeBarTrack:"spotnav-charge-bar-track",chargeBarFill:"spotnav-charge-bar-fill",chargeBarLine:"spotnav-charge-bar-line",graphSurface:"spotnav-graph",viewport:"spotnav-chart-viewport",svg:"spotnav-svg",bands:"spotnav-bands",bandInstalled:"spotnav-band-installed",bandProposal:"spotnav-band-proposal",bandTomorrow:"spotnav-band-tomorrow",bandHatch:"spotnav-band-hatch",axis:"spotnav-axis",gridline:"spotnav-gridline",axisLabel:"spotnav-axis-label",tickLabel:"spotnav-tick-label",dayDivider:"spotnav-day-divider",dayLabel:"spotnav-day-label",now:"spotnav-now",selection:"spotnav-selection",marks:"spotnav-marks",point:"spotnav-point",segment:"spotnav-segment",current:"spotnav-current",cheap:"spotnav-cheap",expensive:"spotnav-expensive",tomorrow:"spotnav-tomorrow",readout:"spotnav-readout",readoutHint:"spotnav-readout-hint",legend:"spotnav-legend",summary:"spotnav-summary",figures:"spotnav-figures",figure:"spotnav-figure",figureLabel:"spotnav-figure-label",figureValue:"spotnav-figure-value",periods:"spotnav-periods",periodsProposal:"spotnav-periods-proposal",periodsInstalled:"spotnav-periods-installed",periodsHeading:"spotnav-periods-heading",period:"spotnav-period",periodActive:"spotnav-period-active",context:"spotnav-context",overlay:"spotnav-dialog-overlay",dialog:"spotnav-dialog",dialogHeader:"spotnav-dialog-header",dialogTitle:"spotnav-dialog-title",dialogClose:"spotnav-dialog-close",dialogIntro:"spotnav-dialog-intro",dialogBody:"spotnav-dialog-body",dialogScroll:"spotnav-dialog-scroll",dialogScrolled:"spotnav-dialog-scrolled",dialogFooter:"spotnav-dialog-footer",issueItem:"spotnav-issue",issueText:"spotnav-issue-text",capabilityItem:"spotnav-capability",capabilityLabel:"spotnav-capability-label",capabilityState:"spotnav-capability-state",capabilityNote